//! Shared model adapter for anchored workspace workers. No model lives in a worker.
fn index_worker_failure(error:impl std::fmt::Display)->String {format!("{}{error}",atlas_joined_probe::INDEX_ABORT_PREFIX)}
use serde_json::{json,Value};
use crate::{workspace_worker::Workers,semantic::SemanticService};
use sha2::{Digest,Sha256};
pub(crate) type VectorCache=std::collections::HashMap<String,Box<[f32;512]>>;
pub(crate) fn input_key(field:&str,title:&str,text:&str)->String {let input=atlas_joined_probe::embedding_text(field,title,text);format!("{:x}",Sha256::digest(input.as_bytes()))}
pub(crate) fn make_cache(index:&atlas_faiss_probe::Index,records:&[Value])->VectorCache{make_cache_partial(index,records,records.len())}
pub(crate) fn make_cache_partial(index:&atlas_faiss_probe::Index,records:&[Value],count:usize)->VectorCache{let mut out=VectorCache::new();if index.count()!=count as i64{return out}for (i,r) in records.iter().take(16000).enumerate(){let field=r["field"].as_str().unwrap_or("");let key=if field=="image"{r["input_hash"].as_str().map(str::to_owned)}else{match (r["title"].as_str(),r["text"].as_str()){(Some(title),Some(text))=>Some(input_key(field,title,text)),_=>None}};if let Some(key)=key{if let Ok(v)=index.reconstruct(i as i64){out.insert(key,Box::new(v));}}}out}
type R<T>=Result<T,Box<dyn std::error::Error>>;
fn call(workers:&Workers,id:&str,session:&str,value:Value)->R<Value>{let result=workers.request_session(id,session,&value)?;if let Some(e)=result["error"].as_str(){return Err(e.to_owned().into())}result.get("ok").cloned().ok_or_else(||"invalid worker response".into())}
fn source_call(workers:&Workers,id:&str,session:&str,value:Value,mut keep_going:impl FnMut()->bool)->R<Value>{let mut result=call(workers,id,session,value.clone())?;let mut task_id=result["task_id"].as_str().unwrap_or("").to_owned();while result["source_busy"]==true||result["pending"]==true{if !keep_going(){let _=call(workers,id,session,json!({"action":"index-abort"}));return Err("cancelled".into())}std::thread::sleep(std::time::Duration::from_millis(30));if result["source_busy"]==true{result=call(workers,id,session,value.clone())?;if let Some(id)=result["task_id"].as_str(){task_id=id.to_owned();}}else{result=call(workers,id,session,json!({"action":"index-source-poll","id":task_id}))?;}}Ok(result)}
fn download_image(mut send:impl FnMut(Value)->R<Value>,docid:&str,hidden:bool)->R<Vec<u8>>{
 let opened=send(json!({"action":"download-begin","id":docid,"hidden":hidden})).map_err(index_worker_failure)?;
 let stream=opened["stream"].as_str().ok_or_else(||index_worker_failure("missing stream"))?.to_owned();
 let result=(||->R<Vec<u8>>{let size=opened["size"].as_u64().ok_or_else(||index_worker_failure("missing size"))?;if size>32*1024*1024{return Err(index_worker_failure("Изображение превышает предел 32 МиБ").into())}let mut bytes=Vec::new();loop {let block=send(json!({"action":"download-next","stream":stream})).map_err(index_worker_failure)?;let list=block["bytes"].as_array().ok_or_else(||index_worker_failure("invalid bytes"))?;for byte in list{let value=byte.as_u64().and_then(|n|u8::try_from(n).ok()).ok_or_else(||index_worker_failure("invalid byte"))?;bytes.push(value);if bytes.len() as u64>size{return Err(index_worker_failure("image exceeds declared size").into())}}let done=block["done"].as_bool().ok_or_else(||index_worker_failure("invalid download status"))?;if done {if bytes.len() as u64!=size{return Err(index_worker_failure("incomplete image").into())}break}if list.is_empty(){return Err(index_worker_failure("empty download chunk").into())}}Ok(bytes)})();
 if result.is_err(){let _=send(json!({"action":"download-cancel","stream":stream}));}result
}
pub fn rebuild(workers:&Workers,id:&str,service:&SemanticService)->R<()> {let session=workers.session(id)?;rebuild_session(workers,id,&session,service)}
pub fn rebuild_session(workers:&Workers,id:&str,session:&str,service:&SemanticService)->R<()> {
 rebuild_control(workers,id,session,service,|_,_|true,||{let mut result=call(workers,id,session,json!({"action":"index-commit"}))?;while result["pending"]==true{std::thread::sleep(std::time::Duration::from_millis(50));result=call(workers,id,session,json!({"action":"index-commit-poll"}))?;}Ok(())})
}
struct IndexAbort<F:FnOnce()> { cleanup:Option<F> }
impl<F:FnOnce()> IndexAbort<F> {fn new(cleanup:F)->Self{Self{cleanup:Some(cleanup)}} fn disarm(&mut self){self.cleanup=None;}}
impl<F:FnOnce()> Drop for IndexAbort<F> {fn drop(&mut self){if let Some(cleanup)=self.cleanup.take(){cleanup()}}}
pub fn rebuild_control(workers:&Workers,id:&str,session:&str,service:&SemanticService,progress:impl FnMut(&str,usize)->bool,commit:impl FnOnce()->R<()>)->R<()> {rebuild_control_mode(workers,id,session,service,false,progress,commit)}
pub fn rebuild_control_mode(workers:&Workers,id:&str,session:&str,service:&SemanticService,force:bool,mut progress:impl FnMut(&str,usize)->bool,commit:impl FnOnce()->R<()>)->R<()> {
 let mut abort=None;let mut completed=0usize;let (model,alternate)=service.worker_model_identities()?;let mut after:Option<String>=None;let mut revision:Option<String>=None;let mut hidden=false;
 loop {let page=source_call(workers,id,session,json!({"action":"index-snapshot","after":after,"images":service.worker_images_enabled(),"hidden":hidden}),||progress("Подготовка индекса",completed))?;let current=page["revision"].as_str().ok_or("missing revision")?;
  if let Some(expected)=&revision {if expected!=current{return Err("workspace changed during indexing".into())}}else{revision=Some(current.to_owned());let mut begin=call(workers,id,session,json!({"action":"index-begin","revision":current,"model":model,"alternate_model":alternate,"force":force}))?;while begin["pending"]==true{if !progress("Подготовка индекса",completed){let _=call(workers,id,session,json!({"action":"index-abort"}));return Err("cancelled".into())}std::thread::sleep(std::time::Duration::from_millis(50));begin=call(workers,id,session,json!({"action":"index-begin-poll"}))?;}abort=Some(IndexAbort::new(||{let _=call(workers,id,session,json!({"action":"index-abort"}));}));}
  for doc in page["documents"].as_array().ok_or("missing documents")? {let docid=doc["id"].as_str().ok_or("missing id")?;let title=doc["title"].as_str().ok_or("missing title")?;if !progress(title,completed){return Err("cancelled".into())}let mut offset=0u64;
   loop {let chunks=source_call(workers,id,session,json!({"action":"index-chunks","revision":current,"id":docid,"offset":offset,"hidden":hidden}),||progress(title,completed))?;if chunks["revision"].as_str()!=Some(current){return Err("workspace changed during indexing".into())}if offset==0{chunks["body_empty"].as_bool().ok_or("missing body status")?;}for chunk in chunks["chunks"].as_array().ok_or("missing chunks")? {if !progress(title,completed){return Err("cancelled".into())}let content=chunk["text"].as_str().ok_or("missing chunk")?;let input=atlas_joined_probe::embedding_text(chunk["field"].as_str().unwrap_or("body"),title,content);let key=input_key(chunk["field"].as_str().unwrap_or("body"),title,content);let cached=call(workers,id,session,json!({"action":"index-reuse","key":key}))?;let fresh=!cached["vector"].is_array();let vector=if !fresh{cached["vector"].clone()}else{{let callback=std::cell::RefCell::new(&mut progress);json!(service.worker_encode_index(&model,input,||(*callback.borrow_mut())(title,completed))?)}};let record=json!({"input_hash":key,"id":docid,"title":title,"field":chunk["field"],"text":content,"start":chunk["start"],"end":chunk["end"],"start_utf16":chunk["start_utf16"],"end_utf16":chunk["end_utf16"],"vector":vector});call(workers,id,session,json!({"action":"index-add","records":[record],"hidden":hidden,"fresh":fresh}))?;completed+=1;}match chunks["next"].as_u64(){Some(next)=>offset=next,None=>break}}
   if service.worker_images_enabled() {let lower=title.to_ascii_lowercase();let mime=if lower.ends_with(".png"){Some("image/png")}else if lower.ends_with(".jpg")||lower.ends_with(".jpeg"){Some("image/jpeg")}else if lower.ends_with(".webp"){Some("image/webp")}else if lower.ends_with(".gif"){Some("image/gif")}else{None};if let Some(mime)=mime {let image=download_image(|value|call(workers,id,session,value),docid,hidden);match image.and_then(|bytes|{let key=format!("image:{mime}:{:x}",Sha256::digest(&bytes));let cached=call(workers,id,session,json!({"action":"index-reuse","key":key})).map_err(index_worker_failure)?;let fresh=!cached["vector"].is_array();let vector=if !fresh{cached["vector"].clone()}else{{let callback=std::cell::RefCell::new(&mut progress);json!(service.worker_encode_image_index(&model,&bytes,mime,||(*callback.borrow_mut())(title,completed))?)}};Ok((key,vector,fresh))}){Ok((key,vector,fresh))=>{call(workers,id,session,json!({"action":"index-add","records":[{"input_hash":key,"id":docid,"title":title,"field":"image","text":"","start":null,"end":null,"vector":vector}],"hidden":hidden,"fresh":fresh}))?;},Err(e)=>{if force||atlas_joined_probe::index_abort_error(&e.to_string()){return Err(format!("{e} ({title})").into())}eprintln!("Atlas: image indexing skipped: {e}")}}}}
  }
  after=page["next"].as_str().map(str::to_owned);if after.is_none(){if !hidden{hidden=true;}else{break}}
 }
 loop {if !progress("Обновление индекса",completed)||!service.index_enabled()||service.worker_model_identity()?!=model{return Err("cancelled".into())}let state=call(workers,id,session,json!({"action":"index-prepare-step"}))?;if state["done"]==true{break}if state["done"]!=false{return Err("invalid index preparation status".into())}}
 service.with_model_identity(&model,||commit().map_err(|e|e.to_string()))?;if let Some(guard)=abort.as_mut(){guard.disarm();}Ok(())
}
pub fn search(workers:&Workers,id:&str,service:&SemanticService,query:&str,ids:Option<&[String]>)->R<Value>{let session=workers.session(id)?;search_session(workers,id,&session,service,query,ids)}
pub fn search_session(workers:&Workers,id:&str,session:&str,service:&SemanticService,query:&str,ids:Option<&[String]>)->R<Value>{let (model,alternate)=service.worker_model_identities()?;let vector=service.worker_encode_expected(&model,query,true)?;let response=call(workers,id,session,json!({"action":"index-search","model":model,"alternate_model":alternate,"vector":vector,"ids":ids}))?;if service.worker_model_identity()?!=model{return Err("Модель поиска изменилась".into())}let mut results=Vec::new();for item in response["results"].as_array().ok_or("invalid worker results")?{let chunks=if item["field"]=="title"{vec![]}else{vec![json!({"text":item["text"],"field":item["field"],"start":item["start"],"end":item["end"],"start_utf16":item["start_utf16"],"end_utf16":item["end_utf16"],"score":item["score"]})]};results.push(json!({"id":item["id"],"title":item["title"],"score":item["score"],"chunks":chunks}));}Ok(json!({"revision":response["revision"],"results":results}))}
#[cfg(feature="test-hook")]
pub fn probe()->R<()> {use std::{fs,io::Read};let mut input=String::new();std::io::stdin().read_to_string(&mut input)?;let v:Value=serde_json::from_str(&input)?;let dir=fs::File::open(v["workspace"].as_str().ok_or("workspace")?)?;let service=SemanticService::start(v["exe"].as_str().ok_or("exe")?,v["model"].as_str().ok_or("model")?)?;let workers=Workers::default();let id="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";workers.attach(id,&dir,std::path::Path::new(v["workspace"].as_str().ok_or("workspace")?))?;rebuild(&workers,id,&service)?;let result=search(&workers,id,&service,v["query"].as_str().ok_or("query")?,None)?;println!("{}",result);Ok(())}
#[cfg(test)] mod reuse_tests {
 use super::*;
 #[test] fn rename_does_not_change_text_chunk_key(){
  assert_eq!(input_key("body","старое","Один текст"),input_key("body","новое","Один текст"));
  assert_eq!(input_key("description","старое","Описание"),input_key("description","новое","Описание"));
  assert_eq!(input_key("title","старое",""),input_key("title","новое",""));
 }
 #[test] fn pending_index_is_aborted_on_error_and_retained_on_success(){
  use std::cell::Cell;let count=Cell::new(0);
  let fail=||->R<()>{let _guard=IndexAbort::new(||count.set(count.get()+1));Err("injected indexing error".into())};assert!(fail().is_err());assert_eq!(count.get(),1);
  {let mut guard=IndexAbort::new(||count.set(count.get()+1));guard.disarm();}assert_eq!(count.get(),1);
 }
 #[test] fn large_cache_is_bounded_and_retains_first_vectors(){
  let mut index=atlas_faiss_probe::Index::new().unwrap();let vector=[0.5f32;512];let mut records=Vec::new();
  for i in 0..16001 {index.add(&[vector]).unwrap();records.push(json!({"field":"body","title":"Title","text":format!("fragment {i}")}));}
  let cache=make_cache(&index,&records);assert_eq!(cache.len(),16000);assert_eq!(cache[&input_key("body","Title","fragment 0")][0],0.5);assert!(!cache.contains_key(&input_key("body","Title","fragment 16000")));assert!(cache.contains_key(&input_key("body","Changed","fragment 0")));
 }
}

#[cfg(test)] mod download_limit_tests {use super::*;#[test] fn large_image_is_reported_and_stream_cancelled(){let mut cancel=false;let result=download_image(|value|match value["action"].as_str().unwrap(){"download-begin"=>Ok(json!({"stream":"s","size":33554433})),"download-cancel"=>{cancel=true;Ok(json!({}))},_=>panic!()},"id",false);let err=result.unwrap_err().to_string();assert!(atlas_joined_probe::index_abort_error(&err));assert!(err.contains("32 МиБ"));assert!(cancel);}}
#[cfg(test)] mod image_transport_tests { #[test] fn reuse_failure_aborts_index(){let e=super::index_worker_failure("worker disconnected during index-reuse");assert!(atlas_joined_probe::index_abort_error(&e));} }

#[cfg(test)] mod download_validation_tests {use super::*;#[test] fn malformed_chunk_aborts_and_cleans_stream(){let mut actions=Vec::new();let result=download_image(|value|{let action=value["action"].as_str().unwrap().to_string();actions.push(action.clone());match action.as_str(){"download-begin"=>Ok(json!({"stream":"s","size":1})),"download-next"=>Ok(json!({"bytes":[999],"done":true})),"download-cancel"=>Ok(json!({})),_=>panic!()}},"id",false);assert!(atlas_joined_probe::index_abort_error(&result.unwrap_err().to_string()));assert_eq!(actions,["download-begin","download-next","download-cancel"]);} }
